// api.js
import axios from 'axios';

const API_URL = 'http://localhost:3001/api';

const refreshAccessToken = async () => {
  const refreshToken = localStorage.getItem('refresh_token');
  if (!refreshToken) {
    console.error("No refresh token available.");
    return null;
  }
  try {
    const response = await axios.post('http://localhost:3001/api/refresh-token', { refresh_token: refreshToken });
    const { access_token } = response.data;
    localStorage.setItem('access_token', access_token);
    return access_token;
  } catch (error) {
    console.error("Error refreshing access token:", error);
    return null;
  }
};

export const exchangeToken = async (code) => {
  try {
    console.log("Requesting token exchange with code:", code);
    const response = await axios.post(`${API_URL}/exchange-token`, { code });
    console.log("Token exchange response:", response.data);
    return response.data;
  } catch (error) {
    console.error("Error exchanging code for token:", error);
    throw error;
  }
};

export const searchTracks = async (query) => {
  const accessToken = localStorage.getItem('access_token');
  console.log("Using access token for search:", accessToken);

  if (!accessToken) {
    console.error("No access token found for searchTracks.");
    return [];
  }

  try {
    console.log("Using access token for search:", accessToken);
    const response = await axios.get(`${API_URL}/search-tracks`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      params: { query },
    });
    console.log("Search response data:", response.data);
    return response.data;
  } catch (error) {
    console.error("Error fetching tracks:", error);
    return [];
  }
};

export const getTrackDetails = async (trackId) => {
  try {
    const response = await axios.get(`${API_URL}/track-details`, { params: { trackId } });
    return response.data;
  } catch (error) {
    console.error('Error fetching track details:', error);
    throw error;
  }
};

export const searchSimilarTracks = async (criteria) => {
  try {
    const response = await axios.get(`${API_URL}/search-similar-tracks`, {
      params: criteria, // criteria will hold details like tempo, genre, etc.
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching similar tracks:', error);
    return [];
  }
};


export const getTrackWithGenre = async (trackId) => {
  console.log("getTrackWithGenre:Fetching track details with genre for track ID:", trackId);
  let accessToken = localStorage.getItem('access_token');
  console.log("getTrackWithGenre:Using access token for getTrackWithGenre:", accessToken);

  if (!accessToken) {
    console.error("No access token found for getTrackWithGenre.");
    return null;
  }

  try {
    // First, attempt to get audio features for similarity
    const featuresResponse = await axios.get(`https://api.spotify.com/v1/audio-features/${trackId}`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    // Now, get track data to retrieve the artist ID
    const trackResponse = await axios.get(`https://api.spotify.com/v1/tracks/${trackId}`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const track = trackResponse.data;
    const artistId = track.artists[0].id;

    // Retrieve genres by fetching artist information
    const artistResponse = await axios.get(`https://api.spotify.com/v1/artists/${artistId}`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const genres = artistResponse.data.genres;
    console.log("Fetched genres for track ID", trackId, ":", genres);

    return { ...featuresResponse.data, genres };

  } catch (error) {
    console.error("Error fetching track details with genre:", error.response?.data || error.message);

    // Check if error is due to token expiration, then refresh and retry
    if (error.response && error.response.status === 401) {
      console.warn("Access token expired. Refreshing token...");

      // Refresh the access token
      await refreshAccessToken();
      accessToken = localStorage.getItem('access_token');

      // Retry the request
      try {
        const featuresResponse = await axios.get(`https://api.spotify.com/v1/audio-features/${trackId}`, {
          headers: { Authorization: `Bearer ${accessToken}` },
        });
        const trackResponse = await axios.get(`https://api.spotify.com/v1/tracks/${trackId}`, {
          headers: { Authorization: `Bearer ${accessToken}` },
        });
        const artistResponse = await axios.get(`https://api.spotify.com/v1/artists/${trackResponse.data.artists[0].id}`, {
          headers: { Authorization: `Bearer ${accessToken}` },
        });
        const genres = artistResponse.data.genres;
        console.log("Refreshed token and fetched genres:", genres);

        return { ...featuresResponse.data, genres };
      } catch (retryError) {
        // console.error("Retry failed after refreshing token:", retryError);
        return null;
      }
    }

    return null;
  }
};
